// ─── File: StructuralDemo.java ───
package com.bank.structural;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class StructuralDemo {
    private static final Logger log = Logger.getLogger(StructuralDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // ADAPTER
        LedgerPort ledger = new LegacyLedgerAdapter(new LegacyLedger());
        ledger.post("SAV2001", new BigDecimal("50000"));

        // DECORATOR: stack logging over encryption over base
        Notifier notifier = new LoggingNotifier(new EncryptingNotifier(new BaseNotifier()));
        notifier.send("+91-98765-00001", "Rs.50000 debited");

        // COMPOSITE: portfolio of holdings + a sub-portfolio
        Portfolio rajeshPortfolio = new Portfolio("Rajesh");
        rajeshPortfolio.add(new Holding("RELIANCE", new BigDecimal("245000")));
        Portfolio mutualFunds = new Portfolio("MF");
        mutualFunds.add(new Holding("NIFTY-INDEX", new BigDecimal("100000")));
        rajeshPortfolio.add(mutualFunds);
        log.info(() -> "Rajesh total portfolio value = Rs." + rajeshPortfolio.marketValue());

        // PROXY: authorization before access
        AccountService svc = new SecureAccountProxy(new RealAccountService(), "TELLER");
        log.info(() -> "Balance (authorized): Rs." + svc.getBalance("SAV2001"));

        // FACADE: one call hides validation + ledger + notify
        TransferFacade facade = new TransferFacade(ledger, notifier);
        facade.transfer("SAV2001", "CUR3001", new BigDecimal("10000"));
    }
}

// ─── ADAPTER ───
interface LedgerPort { void post(String accountId, BigDecimal amount); }
class LegacyLedger { void writeEntry(String acct, double amt) {
    Logger.getLogger("LEDGER").info("legacy writeEntry " + acct + " " + amt); } }
class LegacyLedgerAdapter implements LedgerPort {
    private final LegacyLedger legacy;
    LegacyLedgerAdapter(LegacyLedger l) { this.legacy = l; }
    public void post(String accountId, BigDecimal amount) { legacy.writeEntry(accountId, amount.doubleValue()); }
}

// ─── DECORATOR ───
interface Notifier { void send(String to, String msg); }
class BaseNotifier implements Notifier {
    public void send(String to, String msg) { Logger.getLogger("NOTIFY").info("SEND to " + to + ": " + msg); }
}
class LoggingNotifier implements Notifier {
    private final Notifier inner; LoggingNotifier(Notifier n){ this.inner=n; }
    public void send(String to, String msg) { Logger.getLogger("NOTIFY").info("LOG: sending to " + to); inner.send(to, msg); }
}
class EncryptingNotifier implements Notifier {
    private final Notifier inner; EncryptingNotifier(Notifier n){ this.inner=n; }
    public void send(String to, String msg) { inner.send(to, "ENC(" + msg + ")"); }
}

// ─── COMPOSITE ───
interface PortfolioComponent { BigDecimal marketValue(); }
class Holding implements PortfolioComponent {
    private final String symbol; private final BigDecimal value;
    Holding(String s, BigDecimal v){ symbol=s; value=v; }
    public BigDecimal marketValue(){ return value; }
}
class Portfolio implements PortfolioComponent {
    private final String name; private final List<PortfolioComponent> children = new ArrayList<>();
    Portfolio(String n){ name=n; }
    void add(PortfolioComponent c){ children.add(c); }
    public BigDecimal marketValue(){
        return children.stream().map(PortfolioComponent::marketValue).reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}

// ─── PROXY ───
interface AccountService { BigDecimal getBalance(String accountId); }
class RealAccountService implements AccountService {
    public BigDecimal getBalance(String accountId) { return new BigDecimal("949950"); }
}
class SecureAccountProxy implements AccountService {
    private final AccountService real; private final String role;
        SecureAccountProxy(AccountService real, String role){ this.real=real;
        this.role=role; }
    public BigDecimal getBalance(String accountId) {
        if (!"TELLER".equals(role) && !"ADMIN".equals(role))
            throw new SecurityException("Not authorized to read balance");
        return real.getBalance(accountId);
    }
}

// ─── FACADE ───
class TransferFacade {
    private final LedgerPort ledger; private final Notifier notifier;
    private static final Logger log = Logger.getLogger(TransferFacade.class.getName());
        TransferFacade(LedgerPort l, Notifier n){ this.ledger=l;
        this.notifier=n; }
    void transfer(String from, String to, BigDecimal amount) {
        if (amount.signum() <= 0) throw new IllegalArgumentException("amount>0");
        ledger.post(from, amount);
        notifier.send("+91-00000", "Rs." + amount + " " + from + "->" + to);
        log.info(() -> "Facade transfer complete " + from + "->" + to);
    }
}

class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
